import numpy as np, mujoco
from scipy.spatial.transform import Rotation
class Controller:
 def __init__(self,s):
  self.s=s;self.m=s.model;self.d=s.data;m=self.m;d=self.d
  self.mid=m.actuator_ctrlrange.mean(1);self.scale=np.ptp(m.actuator_ctrlrange,axis=1)/2
  self.u=np.zeros(m.nu);self.u[:21]=d.qpos[m.jnt_qposadr[m.actuator_trnid[:21,0]]]
  self.u[[0,1,5,6,10]]=0;self.u[[2,7]]=-.4;self.u[[3,8]]=.8;self.u[[4,9]]=-.4
  self.base=self.u.copy();self.ikd=mujoco.MjData(m)
  self.jids={hand:np.array([m.actuator(i).trnid[0] for i in idx]) for hand,idx in [('left',[11,12,13,14,15,21,22]),('right',[16,17,18,19,20,41,42])]}
  self.aids={'left':np.array([11,12,13,14,15,21,22]),'right':np.array([16,17,18,19,20,41,42])}
  self.qids={h:m.jnt_qposadr[j] for h,j in self.jids.items()};self.vids={h:m.jnt_dofadr[j] for h,j in self.jids.items()}
  self.pids={'left':m.body('lh_palm').id,'right':m.body('rh_palm').id}
 def ik(self,hand,pos,rot=None,offset=np.zeros(3),nit=8):
  m=self.m;d=self.ikd;d.qpos[:]=self.d.qpos
  qi=self.qids[hand];vi=self.vids[hand];ai=self.aids[hand];bid=self.pids[hand]
  d.qpos[qi]=self.u[ai]
  for _ in range(nit):
   mujoco.mj_fwdPosition(m,d)
   r=d.xmat[bid].reshape(3,3);p=d.xpos[bid]+r@offset
   jp=np.zeros((3,m.nv));jr=np.zeros((3,m.nv));mujoco.mj_jac(m,d,jp,jr,p,bid)
   err=pos-p;J=jp[:,vi]
   if rot is not None:
    er=Rotation.from_matrix(rot@r.T).as_rotvec();err=np.r_[err,.25*er];J=np.vstack([J,.25*jr[:,vi]])
   dq=J.T@np.linalg.solve(J@J.T+np.eye(len(err))*1e-4,err)
   d.qpos[qi]=np.clip(d.qpos[qi]+np.clip(dq,-.15,.15),m.jnt_range[self.jids[hand],0],m.jnt_range[self.jids[hand],1])
  self.u[ai]=d.qpos[qi]
  return np.linalg.norm(err)
 def action(self,balance=False,grav=True):
  u=self.u.copy();m=self.m;d=self.d
  if grav:
   for i in range(21):
    vi=m.jnt_dofadr[m.actuator_trnid[i,0]]
    u[i]+=d.qfrc_bias[vi]/m.actuator_gainprm[i,0]
  if balance:
   cx=d.subtree_com[1,0];vx=d.subtree_linvel[1,0];feet=(d.site('left_foot').xpos+d.site('right_foot').xpos)/2
   # Add restoring torque when centre of mass moves in front of support.
   u[[4,9]]+=3*(cx-feet[0]-.025)+.9*vx
   roll=Rotation.from_quat(d.qpos[[4,5,6,3]]).as_euler('xyz')[0]
   u[[1,6]]-=.8*roll+.2*d.qvel[3]
  return np.clip((u-self.mid)/self.scale,-1,1)
